import sys

def lcs_len(a: str, b: str) -> int:
    if not a or not b:
        return 0
    if len(a) > len(b):
        a, b = b, a
    m = len(a)
    if m == len(b) and a == b:
        return m
    pos = {}
    for i, ch in enumerate(a):
        pos[ch] = pos.get(ch, 0) | (1 << i)

    S = (1 << m) - 1
    mask = S
    for ch in b:
        pm = pos.get(ch, 0)
        if pm:
            u = S & pm
            S = (S + u) | (S - u)
    return m - (S & mask).bit_coun
